const int START = 2;
const int STOP = 3;
const int MOTOR = 8;
bool running = false;

void setup() {
  pinMode(START, INPUT_PULLUP);
  pinMode(STOP, INPUT_PULLUP);
  pinMode(MOTOR, OUTPUT);
}

void loop() {
  bool start = digitalRead(START) == LOW;
  bool stopPressed = digitalRead(STOP) == LOW;
  running = (start || running) && !stopPressed;
  digitalWrite(MOTOR, running ? HIGH : LOW);
}
